const rawOutput = $input.first().json.output || 
                  $input.first().json.text || 
                  "Hello! How can I help you today?";

// Remove routing word at the end
const cleanOutput = rawOutput
  .replace(/\n*(teaching|quiz|research|assessment)\s*$/i, "")
  .trim();

// Detect response type for styling
const isQuiz = /quiz|question|test/i.test(rawOutput);
const isResearch = /research|paper|study|academic/i.test(rawOutput);
const isAssessment = /assessment|evaluation|past paper/i.test(rawOutput);
const isGreeting = /hello|hi |hey|greet|welcome/i.test(rawOutput);

// Set theme color based on type
const themeColor = isQuiz ? "#e74c3c" : 
                   isResearch ? "#27ae60" : 
                   isAssessment ? "#e67e22" : 
                   isGreeting ? "#2980b9" : "#667eea";

const themeIcon = isQuiz ? "📝" : 
                  isResearch ? "🔬" : 
                  isAssessment ? "📋" : 
                  isGreeting ? "👋" : "📚";

const themeLabel = isQuiz ? "Quiz Mode" : 
                   isResearch ? "Research Mode" : 
                   isAssessment ? "Assessment Mode" : 
                   isGreeting ? "AI Virtual Tutor" : "Teaching Mode";

const htmlEmail = `
