return [{ json: { htmlEmail } }];

// n8n Code node — Validation Layer
// Place between: If node → this node → Markdown node

const VALID_ROUTES = ['teacher', 'quiz', 'research', 'assessment'];

const item = $input.first();
const body = item.json;

// 1. Check output is non-empty
const content = body?.output ?? body?.text ?? body?.content ?? null;
if (!content || String(content).trim() === '') {
  throw new Error('VALIDATION_FAIL: AI Agent returned empty output');
}

// 2. Check routing key is valid (if present)
const route = body?.route ?? body?.agent ?? null;
if (route && !VALID_ROUTES.includes(String(route).toLowerCase())) {
  throw new Error(`VALIDATION_FAIL: Unknown routing key "${route}". Expected one of: ${VALID_ROUTES.join(', ')}`);
}

// 3. Check response is parseable if it looks like JSON
const trimmed = String(content).trim();
if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
  try {
    JSON.parse(trimmed);
  } catch {
    throw new Error('VALIDATION_FAIL: Response appears to be JSON but could not be parsed');
  }
}

// All checks passed — pass item through cleanly
return [{ json: { ...body, _validated: true, _route: route ?? 'default' } }];
